-- Node 284 (S2-4.1) rev 2 -> 3
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 2;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 284 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 284: expected %, got %', v_expected, v_actual;
  END IF;
