  v_actual INT;
  v_expected INT := 2;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 285 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 285: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (285, 3, $p1b_285$[{"t": "list", "id": "s2-4-2-b1", "imp": "core", "items": ["1、==视图检索（查询）==", "（1）语法：==`SELECT * FROM 视图名;`==", "（2）使用说明：使用视图就像和使用基本表一样，可以简单查询，也可以联合查询（UNION），也可连接查询，也可以排序、分组等，==视图不能索引操作==。", "（3）实例：`SELECT * FROM v_student1;`", "2、==视图修改本表中数据==", "（1）==MySQL 允许一定条件下通过视图对基本表的数据修改（增加、删除、修改）操作。==", "（2）@@如果视图中包含以下是不被允许更新操作的：@@"], "title": "", "ordered": false}, {"h": 447, "t": "img", "w": 790, "id": "s2-4-2-b2", "imp": "normal", "src": "/kb-assets/skill/p82_r0_5a2ef8632937352b.png", "title": "", "alt": "MySQL 视图禁止执行更新操作的 8 类常见限制条件导图", "caption": "视图不可直接修改基本表数据的常见受限情形汇总（含聚合函数、DISTINCT、GROUP BY、子查询等）"}, {"t": "list", "id": "s2-4-2-b3", "imp": "core", "items": ["3、==通过视图向基本表中插入数据==", "（1）语法：==`INSERT INTO 表名 (列名列表) VALUES (值列表);`==", "（2）实例：`- 向视图中插入一条记录：` `INSERT INTO v_temp1 (name, age) VALUES ('吴越', 19);`", "4、==通过视图向基本表中修改数据==", "（1）语法：==`UPDATE 视图名 SET 属性名 = 新值 [WHERE 条件];`==", "（2）实例：`- 通过视图将吴越年龄加 1：` `UPDATE v_temp1 SET age = age + 1 WHERE name = '吴越';`", "5、==通过视图向基本表中删除数据==", "（1）语法：==`DELETE FROM 视图名 [WHERE 条件];`==", "（2）实例：`- 通过视图删除姓名叫吴越的记录：` `DELETE FROM v_temp1 WHERE name = '吴越';`", "6、==WITH CHECK OPTION 子句==：WITH CHECK OPTION 子句会在更新数据时检查数据是否符合视图定义中 WHERE 子句的条件，并且只能和可更新视图一起使用。"], "title": "", "ordered": false}, {"t": "callout", "id": "s2-4-2-b4", "imp": "normal", "kind": "tip", "text": "通过视图可以简化复杂的联表多层查询逻辑，并能对敏感字段进行安全权限隐藏（只对特定角色开放脱敏后的视图）；但对视图的更新操作（INSERT/UPDATE/DELETE）存在严格约束限制。", "title": "考向复习提示：通过视图检索与修改基表数据的限制条件"}, {"t": "callout", "id": "s2-4-2-b5", "imp": "core", "kind": "trap", "text": "专转本考试必考题：==若一个视图的定义语句中包含了“聚合函数（SUM/AVG/COUNT等）、GROUP BY 分组子句、DISTINCT 去重关键字、UNION 联合运算”中的任何一项，那么该视图在物理上是“绝对不可更新的（Updatable View）”==！试图通过这种汇总视图执行 UPDATE 或 DELETE 会被数据库直接拒绝拦截！", "title": "高频易错陷阱：包含聚合函数或 DISTINCT 的视图不可更新！"}]$p1b_285$::jsonb, '', $p1s_285$S2-4.2 用视图检索和修改基本表中数据。
1、视图检索（查询）
（1）语法：SELECT * FROM 视图名;
（2）使用说明：使用视图就像和使用基本表一样，可以简单查询，也可以联合查询（UNION），也可连接查询，也可以排序、分组等，视图不能索引操作。
（3）实例：SELECT * FROM v_student1;
2、视图修改本表中数据
（1）MySQL 允许一定条件下通过视图对基本表的数据修改（增加、删除、修改）操作。
（2）如果视图中包含以下是不被允许更新操作的：
视图不可直接修改基本表数据的常见受限情形汇总（含聚合函数、DISTINCT、GROUP BY、子查询等）
3、通过视图向基本表中插入数据
（1）语法：INSERT INTO 表名 (列名列表) VALUES (值列表);
（2）实例：- 向视图中插入一条记录： INSERT INTO v_temp1 (name, age) VALUES ('吴越', 19);
4、通过视图向基本表中修改数据
（1）语法：UPDATE 视图名 SET 属性名 = 新值 [WHERE 条件];
（2）实例：- 通过视图将吴越年龄加 1： UPDATE v_temp1 SET age = age + 1 WHERE name = '吴越';
5、通过视图向基本表中删除数据
（1）语法：DELETE FROM 视图名 [WHERE 条件];
（2）实例：- 通过视图删除姓名叫吴越的记录： DELETE FROM v_temp1 WHERE name = '吴越';
6、WITH CHECK OPTION 子句：WITH CHECK OPTION 子句会在更新数据时检查数据是否符合视图定义中 WHERE 子句的条件，并且只能和可更新视图一起使用。
考向复习提示：通过视图检索与修改基表数据的限制条件
通过视图可以简化复杂的联表多层查询逻辑，并能对敏感字段进行安全权限隐藏（只对特定角色开放脱敏后的视图）；但对视图的更新操作（INSERT/UPDATE/DELETE）存在严格约束限制。
高频易错陷阱：包含聚合函数或 DISTINCT 的视图不可更新！
专转本考试必考题：若一个视图的定义语句中包含了“聚合函数（SUM/AVG/COUNT等）、GROUP BY 分组子句、DISTINCT 去重关键字、UNION 联合运算”中的任何一项，那么该视图在物理上是“绝对不可更新的（Updatable View）”！试图通过这种汇总视图执行 UPDATE 或 DELETE 会被数据库直接拒绝拦截！$p1s_285$, $p1r_285${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S2-4.2 用视图检索和修改基本表中数据。", "题库补充：WITH CHECK OPTION 子句 (10题)", "p1_refine_20261114"], "pages": [81, 82], "spans": 14}$p1r_285$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 3, updated_at = NOW() WHERE node_id = 285;
END $$;

