END $$;

-- Node 298 (S3-3.3) rev 2 -> 3
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 2;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 298 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 298: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (298, 3, $p1b_298$[{"t": "list", "id": "s3-3-3-b1", "imp": "core", "items": ["1、画顺序图步骤：", "==(1)确定交互的范围==", "==(2)确定参与交互的活动者与对象==", "==(3)确定活动者、对象的生存周期==", "==(4)确定交互中产生的消息==", "==(5)细化消息的内容==", "2、实例：系统管理员添加书籍的时序图", "3、==交互片段与组合片段==：一个顺序图可以划分为==几个小块==，每一个小块称为一个交互片段。每个交互片段由一个大方框包围，其名称显示在方框左上角的间隔区内，表示该顺序图的信息。 如果把两个或多个片段放在一个交互框架里，各片段的区域之间用一条虚线分隔，则称为组合片段。组合片段常用于表示交互中的条件选择、并发或引用情况。 例：一个包含组合片段的交互框架中，该组合片段有两个交互片段，并发执行。 一个顺序图中可以含有多个交互框架，每一个交互框架可以包含一个或多个片段；一个交互框架中还可以包含另一个交互框架。"], "title": "", "ordered": false}, {"h": 637, "t": "img", "w": 1053, "id": "s3-3-3-b2", "imp": "normal", "src": "/kb-assets/skill/p100_r1_403f7a4558aa0fe8.png", "title": "", "alt": "带有 par 并发组合片段交互框架的 UML 顺序图绘制实例", "caption": "带组合片段（交互框架）顺序图实例：演示 `par` 并发片段划分多子交互域的执行时序"}, {"t": "callout", "id": "s3-3-3-b3", "imp": "normal", "kind": "tip", "text": "绘制顺序图标准流程：\n1. 梳理业务用例的事件流描述；\n2. 识别参与该用例交互的边界对象、控制对象与实体对象；\n3. 将对象自左向右排列并拉出垂直生命线；\n4. 自顶向下按时间发生先后顺序依次绘制水平消息箭头并注明消息参数与返回值；\n5. 必要时使用组合片段（alt 分支条件、loop 循环）。", "title": "考向复习提示：顺序图手绘标准建模步骤"}, {"t": "callout", "id": "s3-3-3-b4", "imp": "core", "kind": "trap", "text": "当对象自己内部调用自己的私有方法时（自调用消息）：==箭头必须从对象的激活期引出，向上或向下折弯成一个‘U’形或矩形半环，再重新指回同一个对象的同一激活条上==；很多考生因为图省事直接在生命线上点个圆点，这在 UML 标准中是非法表达！", "title": "高频易错陷阱：自调用消息（Self Message）的正确画法"}]$p1b_298$::jsonb, '', $p1s_298$S3-3.3 绘制顺序图。
1、画顺序图步骤：
(1)确定交互的范围
(2)确定参与交互的活动者与对象
(3)确定活动者、对象的生存周期
(4)确定交互中产生的消息
(5)细化消息的内容
2、实例：系统管理员添加书籍的时序图
3、交互片段与组合片段：一个顺序图可以划分为几个小块，每一个小块称为一个交互片段。每个交互片段由一个大方框包围，其名称显示在方框左上角的间隔区内，表示该顺序图的信息。 如果把两个或多个片段放在一个交互框架里，各片段的区域之间用一条虚线分隔，则称为组合片段。组合片段常用于表示交互中的条件选择、并发或引用情况。 例：一个包含组合片段的交互框架中，该组合片段有两个交互片段，并发执行。 一个顺序图中可以含有多个交互框架，每一个交互框架可以包含一个或多个片段；一个交互框架中还可以包含另一个交互框架。
带组合片段（交互框架）顺序图实例：演示 par 并发片段划分多子交互域的执行时序
考向复习提示：顺序图手绘标准建模步骤
绘制顺序图标准流程：
1. 梳理业务用例的事件流描述；
2. 识别参与该用例交互的边界对象、控制对象与实体对象；
3. 将对象自左向右排列并拉出垂直生命线；
4. 自顶向下按时间发生先后顺序依次绘制水平消息箭头并注明消息参数与返回值；
5. 必要时使用组合片段（alt 分支条件、loop 循环）。
高频易错陷阱：自调用消息（Self Message）的正确画法
当对象自己内部调用自己的私有方法时（自调用消息）：箭头必须从对象的激活期引出，向上或向下折弯成一个‘U’形或矩形半环，再重新指回同一个对象的同一激活条上；很多考生因为图省事直接在生命线上点个圆点，这在 UML 标准中是非法表达！$p1s_298$, $p1r_298${"pdf": "操作技能复习.pdf", "extra": ["考纲三级节点: S3-3.3 绘制顺序图。", "题库补充：交互片段与组合片段 (31题)", "p1_refine_20261114"], "pages": [100, 101], "spans": 8}$p1r_298$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 3, updated_at = NOW() WHERE node_id = 298;
END $$;

