  v_actual INT;
  v_expected INT := 3;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 322 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 322: expected %, got %', v_expected, v_actual;
  END IF;
